import base64
import json
import os
from typing import Any, Dict, List, Optional, Union

import boto3


def _coerce_file_bytes(source: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(source, (bytes, bytearray)):
        return bytes(source)
    if not isinstance(source, str):
        raise TypeError("invoice_source must be a path, base64 string, or bytes-like object")

    if os.path.exists(source):
        with open(source, "rb") as f:
            return f.read()

    try:
        return base64.b64decode(source, validate=True)
    except Exception as exc:
        raise ValueError("invoice_source must be an existing file path or base64-encoded content") from exc


def _safe_get(dct: Dict[str, Any], *keys: str) -> Any:
    cur: Any = dct
    for key in keys:
        if not isinstance(cur, dict):
            return None
        cur = cur.get(key)
    return cur


def extract_invoice_fields(
    invoice_source: Union[str, bytes, bytearray],
    aws_region: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line items from an invoice using Amazon Textract AnalyzeExpense.

    Returns a dictionary with:
      - vendor: str or None
      - date: str or None
      - total: str or None
      - line_items: list[dict]
    """
    document_bytes = _coerce_file_bytes(invoice_source)

    client = boto3.client("textract", region_name=aws_region)
    response = client.analyze_expense(Document={"Bytes": document_bytes})

    expense_docs = response.get("ExpenseDocuments", []) or []
    if not expense_docs:
        return {"vendor": None, "date": None, "total": None, "line_items": []}

    doc = expense_docs[0]

    summary_fields = doc.get("SummaryFields", []) or []
    line_item_groups = doc.get("LineItemGroups", []) or []

    vendor = None
    date = None
    total = None

    for field in summary_fields:
        t = _safe_get(field, "Type", "Text")
        val = _safe_get(field, "ValueDetection", "Text")
        if not t or not val:
            continue

        t_upper = str(t).upper()
        if vendor is None and t_upper in {"VENDOR_NAME", "SUPPLIER_NAME", "RECEIVER_NAME", "PROVIDER_NAME"}:
            vendor = val
        elif date is None and t_upper in {"INVOICE_RECEIPT_DATE", "DOCUMENT_DATE", "ORDER_DATE", "ISSUE_DATE"}:
            date = val
        elif total is None and t_upper in {"TOTAL", "AMOUNT_DUE", "INVOICE_RECEIPT_TOTAL", "SUMMATION"}:
            total = val

    line_items: List[Dict[str, Any]] = []
    for group in line_item_groups:
        for line in group.get("LineItems", []) or []:
            item: Dict[str, Any] = {}
            for field in line.get("LineItemExpenseFields", []) or []:
                field_type = _safe_get(field, "Type", "Text")
                value = _safe_get(field, "ValueDetection", "Text")
                if field_type and value is not None:
                    item[str(field_type).lower()] = value
            if item:
                line_items.append(item)

    result = {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
    }

    return result


def extract_invoice_fields_json(
    invoice_source: Union[str, bytes, bytearray],
    aws_region: Optional[str] = None,
) -> str:
    return json.dumps(extract_invoice_fields(invoice_source, aws_region=aws_region), ensure_ascii=False)
